"""Falsifiable experiment designs. These proposals do not report native results."""

def idea(name,path,hypothesis,intervention,baseline,measure,failure):
    return dict(name=name,path=path,page='research-map',status='Unimplemented experiment design',
                gate='Prove the verifier and define a fixed budget before asking the model to optimize it.',
                protocol=dict(Hypothesis=hypothesis,Intervention=intervention,Baseline=baseline,
                              Measurement=measure,Failure=failure))

